// Deterministic spherical motion shared by simulation and renderer.
export const ORBITAL={radius:2.8,speed:.34,laserDuration:5,damagePerSecond:4};
export function unitAt(point){const lat=point.lat*Math.PI/180,lon=point.lon*Math.PI/180;return [Math.cos(lat)*Math.sin(lon),Math.sin(lat),Math.cos(lat)*Math.cos(lon)];}
export function orbitBasis(origin,target){const a=unitAt(origin),b=unitAt(target),dot=Math.max(-1,Math.min(1,a.reduce((n,x,i)=>n+x*b[i],0)));let tangent=b.map((x,i)=>x-a[i]*dot);let length=Math.hypot(...tangent);if(length<1e-6){tangent=[a[2],0,-a[0]];length=Math.hypot(...tangent);if(length<1e-6){tangent=[1,0,0];length=1;}}return {a,tangent:tangent.map(x=>x/length),angle:Math.acos(dot)};}
export function orbitalPosition(satellite){const {a,tangent,angle}=orbitBasis(satellite.origin,satellite.destination);let phase=0;if(satellite.phase==='transit')phase=angle*Math.min(1,satellite.elapsed/satellite.travel);else if(['firing','charging'].includes(satellite.phase))phase=angle;else if(satellite.phase==='return')phase=angle+(2*Math.PI-angle)*Math.min(1,satellite.elapsed/satellite.returnTime);return a.map((x,i)=>(x*Math.cos(phase)+tangent[i]*Math.sin(phase))*ORBITAL.radius);}
